        @NotBlank String password) {
}

interface NotificationService {
    void send(String recipient, String message);
}

import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Component;

@Component("emailSender")
class EmailSender implements NotificationService {
    @Override
    public void send(String recipient, String message) {
        System.out.println("[email] to=" + recipient + " msg=" + message);
    }
}

@Component("smsSender")
class SmsSender implements NotificationService {
    @Override
    public void send(String recipient, String message) {
        System.out.println("[sms] to=" + recipient + " msg=" + message);
    }
}

class NotificationClient {

    private final NotificationService emailSender;

    // @Qualifier chọn đúng bean khi có nhiều implementation của cùng một
    // interface — Spring resolve theo type trước (như học ở Day 14), rồi
    // dùng tên @Qualifier để phân biệt giữa các ứng viên cùng type.
    NotificationClient(@Qualifier("emailSender") NotificationService emailSender) {
        this.emailSender = emailSender;
    }
}

enum NotificationType { EMAIL, SMS, PUSH }

import java.util.Map;
import org.springframework.stereotype.Component;

@Component
class NotificationSenderFactory {

    private final Map<NotificationType, NotificationService> senders;

    // Spring tiêm toàn bộ các bean NotificationService vào Map, key là
    // tên bean; Factory tự ánh xạ tên bean sang NotificationType để chọn
    // đúng sender mà không cần chuỗi if/else theo type.
    NotificationSenderFactory(Map<String, NotificationService> beansByName) {
        this.senders = Map.of(
                NotificationType.EMAIL, beansByName.get("emailSender"),
                NotificationType.SMS, beansByName.get("smsSender"));
    }

    NotificationService senderFor(NotificationType type) {
        NotificationService sender = senders.get(type);
        if (sender == null) {
            throw new IllegalArgumentException("Không có sender cho: " + type);
        }
        return sender;
    }
}

